-- dev PostgreSQL / DBeaver: 새 SQL 탭에서 파일 전체를 Execute SQL script로 실행한다.
-- 이전 적재 오류가 난 탭은 먼저 ROLLBACK; 한다. 이 파일은 dev에 자동 실행되지 않는다.
-- 대상: daynomy_dev. 1,000명 시드의 기준일 2026-10-29를 유지한다.
-- 미국 20주식 + 10ETF, 2025-10-15~2026-10-28의 실제 종가만 보충한다.
-- 종가 원천: https://eodhd.com/financial-apis/api-for-historical-data-and-volumes
-- API: /api/eod/{symbol}, /api/eod/USDKRW.FOREX (기존 앱과 같은 close 필드).
-- 출처 조회일: 2026-10-30. API 키/회원 정보는 포함하지 않는다.
-- 원본 가격 후보 7,830행(30종목 × 261일), 환율 원본 322행.
-- 실제 INSERT 수는 이미 있는 행을 제외한 수다. 같은 파일 재실행은 안전하다.
-- 기존 종가/환율은 ON CONFLICT DO NOTHING으로 보존한다.
-- assets, 회원, 원장, 스냅샷, 수집 완료 플래그는 변경하지 않는다.
BEGIN;
SET LOCAL TIME ZONE 'Asia/Seoul';
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '5min';

DO $$
BEGIN
    IF current_database() <> 'daynomy_dev' THEN
        RAISE EXCEPTION '대상 DB는 daynomy_dev여야 합니다. 현재 연결을 확인하세요.';
    END IF;
    IF NOT pg_try_advisory_xact_lock(1000, 1) THEN
        RAISE EXCEPTION '다른 부하테스트 데이터 준비 작업이 진행 중입니다.';
    END IF;
END $$;

CREATE TEMP TABLE lt1000_source_prices (
    asset_code text, base_date date, close_price numeric(21,4),
    PRIMARY KEY(asset_code, base_date), CHECK(close_price > 0)
) ON COMMIT DROP;
CREATE TEMP TABLE lt1000_source_fx (
    base_date date PRIMARY KEY, rate numeric(19,6), CHECK(rate > 0)
) ON COMMIT DROP;

