-- 코드로 dev의 기존 종목 ID를 찾는다. dev와 로컬/다른 DB의 ID가 달라도 된다.
CREATE TEMP TABLE lt1000_backfill_assets ON COMMIT DROP AS
SELECT a.id AS asset_id,a.asset_code,a.category,a.market
FROM assets a JOIN (SELECT DISTINCT asset_code FROM lt1000_source_prices) s USING(asset_code)
WHERE a.listed AND a.category IN ('STOCK','ETF')
  AND a.market IN ('NASDAQ','NYSE','NYSE_ARCA','NYSE_AMERICAN','BATS');

DO $$
BEGIN
    IF (SELECT count(*) FROM lt1000_backfill_assets) <> 30
       OR (SELECT count(DISTINCT asset_code) FROM lt1000_backfill_assets) <> 30 THEN
        RAISE EXCEPTION '선정한 미국 30종목이 모두 유일한 상장 주식/ETF로 존재해야 합니다.';
    END IF;
    IF (SELECT count(*) FROM lt1000_source_prices) <> 7830
       OR (SELECT count(DISTINCT base_date) FROM lt1000_source_prices) <> 261 THEN
        RAISE EXCEPTION '파일의 원본 종가 데이터 건수가 예상과 다릅니다.';
    END IF;
    IF EXISTS (
        SELECT FROM stock_daily_prices p JOIN assets a ON a.id=p.asset_id
        WHERE a.listed AND a.category IN ('STOCK','ETF')
          AND a.market IN ('NASDAQ','NYSE','NYSE_ARCA','NYSE_AMERICAN','BATS')
          AND p.base_date >= DATE '2025-10-15' AND p.base_date < DATE '2026-10-29'
          AND NOT EXISTS (SELECT FROM lt1000_source_prices s WHERE s.base_date=p.base_date)
    ) THEN
        RAISE EXCEPTION 'dev의 미국 가격 날짜 중 원본에 없는 날짜가 있습니다. 날짜를 대조한 뒤 실행하세요.';
    END IF;
END $$;

-- 공급자의 수정 등으로 기존 값과 차이가 있는 행 수를 표시하지만 덮어쓰지 않는다.
SELECT 'existing_price_differences_preserved' AS metric,count(*) AS rows
FROM stock_daily_prices p JOIN lt1000_backfill_assets a ON a.asset_id=p.asset_id
JOIN lt1000_source_prices s ON s.asset_code=a.asset_code AND s.base_date=p.base_date
WHERE p.close_price<>s.close_price;

WITH added AS (
    INSERT INTO stock_daily_prices(asset_id,base_date,close_price,created_at,updated_at)
    SELECT a.asset_id,s.base_date,s.close_price,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP
    FROM lt1000_source_prices s JOIN lt1000_backfill_assets a USING(asset_code)
    ON CONFLICT(asset_id,base_date) DO NOTHING RETURNING id
)
SELECT 'us_price_rows_inserted' AS metric,count(*) AS rows FROM added;

-- 모든 미국 종목이 공유하는 가격 날짜에 환율이 필요하다.
CREATE TEMP TABLE lt1000_required_fx ON COMMIT DROP AS
SELECT DISTINCT p.base_date AS requested_date
FROM stock_daily_prices p JOIN assets a ON a.id=p.asset_id
WHERE a.listed AND a.category IN ('STOCK','ETF')
  AND a.market IN ('NASDAQ','NYSE','NYSE_ARCA','NYSE_AMERICAN','BATS')
  AND p.base_date >= DATE '2025-10-15' AND p.base_date < DATE '2026-10-29';

-- 앱과 동일: 요청일 이하 14일 이내에서 가장 최근 실제 환율을 선택한다.
CREATE TEMP TABLE lt1000_prepared_fx ON COMMIT DROP AS
SELECT d.requested_date,f.base_date,f.rate
FROM lt1000_required_fx d
JOIN LATERAL (SELECT f.* FROM lt1000_source_fx f
              WHERE f.base_date BETWEEN d.requested_date-14 AND d.requested_date
              ORDER BY f.base_date DESC LIMIT 1) f ON true;

DO $$
BEGIN
    IF EXISTS (SELECT FROM lt1000_required_fx d
               LEFT JOIN lt1000_prepared_fx f USING(requested_date)
               WHERE f.requested_date IS NULL) THEN
        RAISE EXCEPTION '필요한 날짜의 실제 환율을 찾지 못했습니다. 전체 변경을 롤백하세요.';
    END IF;
END $$;

SELECT 'existing_fx_differences_preserved' AS metric,count(*) AS rows
FROM usd_krw_rates r JOIN lt1000_prepared_fx f USING(requested_date)
WHERE r.base_date<>f.base_date OR r.rate<>f.rate;

WITH added AS (
    INSERT INTO usd_krw_rates(requested_date,base_date,rate,fetched_at)
    SELECT requested_date,base_date,rate,CURRENT_TIMESTAMP FROM lt1000_prepared_fx
    ON CONFLICT(requested_date) DO NOTHING RETURNING requested_date
)
SELECT 'usd_krw_rows_inserted' AS metric,count(*) AS rows FROM added;

DO $$
BEGIN
    IF EXISTS (
        SELECT FROM lt1000_source_prices s JOIN lt1000_backfill_assets a USING(asset_code)
        LEFT JOIN stock_daily_prices p ON p.asset_id=a.asset_id AND p.base_date=s.base_date
        WHERE p.id IS NULL
    ) OR EXISTS (
        SELECT FROM lt1000_required_fx d LEFT JOIN usd_krw_rates r USING(requested_date)
        WHERE r.requested_date IS NULL
    ) THEN
        RAISE EXCEPTION '종가 또는 환율 누락 검증 실패. 전체 변경을 롤백하세요.';
    END IF;
END $$;

SELECT a.asset_code,a.category,count(*) AS price_rows,
       min(p.base_date) AS first_date,max(p.base_date) AS last_date
FROM lt1000_backfill_assets a JOIN stock_daily_prices p ON p.asset_id=a.asset_id
WHERE p.base_date >= DATE '2025-10-15' AND p.base_date < DATE '2026-10-29'
GROUP BY a.asset_code,a.category ORDER BY a.asset_code;

SELECT count(*) AS required_fx_dates,
       count(*) FILTER(WHERE r.requested_date IS NULL) AS missing_fx_dates
FROM lt1000_required_fx d LEFT JOIN usd_krw_rates r USING(requested_date);

COMMIT;
-- 완료 후 seed-portfolio-1000.sql 전체 실행 → verify-portfolio-1000.sql 실행.
